use super::*;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
fn law()->serde_json::Value{serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap()}
fn original()->RetainedCloneGrant{let d=law();let g=&d["grant"];RetainedCloneGrant{maximum_items:g["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:g["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:g["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:g["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:g["maximumDepth"].as_u64().unwrap()as usize}}
fn denials(d:RetirementDemand,g:RetainedCloneGrant)->Vec<RetainedCloneGrant>{let mut result=vec![RetainedCloneGrant{maximum_items:0,..g}];if d.copy_bytes!=0{result.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g});}if d.capacity_bytes!=0{result.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g});}if d.release_bytes!=0{result.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g});}if d.depth!=0{result.push(RetainedCloneGrant{maximum_depth:d.depth-1,..g});}result}
#[test]fn original_retained_byte_page_4096_conserves_backing_through_all_frontiers(){
 let law=law();let g=original();let d=RetainedBytePage::birth_demand();assert!(d.copy_bytes<=g.maximum_copy_bytes&&d.capacity_bytes<=g.maximum_capacity_bytes);
 for denied in denials(d,g){let(result,heap)=observe(||RetainedBytePage::admit(denied).unwrap());assert!(result.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
 for cut in law["cuts"].as_array().unwrap(){let((mut page,p),heap)=observe(||RetainedBytePage::admit(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert_eq!(heap.requested_bytes,4096);let pointer=page.identity();let mut initialized=0;
  for _ in 0..cut.as_u64().unwrap(){if page.ready(){break;}let d=page.initialize_demand().unwrap();for denied in denials(d,g){let(step,heap)=observe(||page.initialize_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(page.identity(),pointer);}let(step,heap)=observe(||page.initialize_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(page.identity(),pointer);initialized+=1;}
  if page.ready(){assert_eq!(page.bytes().unwrap(),&[0;4096]);}else{assert!(page.bytes().is_none());}
  let d=page.close_demand();for denied in denials(d,g){let(step,heap)=observe(||page.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(page.identity(),pointer);}let(step,heap)=observe(||page.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert_eq!(heap.released_bytes,4096);assert!(page.terminal_is_empty());assert_eq!(observe(||drop(page)).1.released_bytes,0);eprintln!("[DEBUG] original byte page4096 cut{cut} initTurns{initialized}: pointer stable, original fixed grant, physical birth4096/release4096, denied heap0 and terminalDrop0");
 }
}
